-- B-N1 Trip Count = count(fact_trip rows)
-- Generated by build_metric_sql.py; edit the generator, not this file.
WITH base AS (
  SELECT f.total_amount, f.fare_amount, f.tip_amount, f.tolls_amount, f.trip_distance,
         f.payment_type, f.od_pair_id, f.pickup_hour, f.vendor_id,
         f.pickup_date, pd.calendar_year, pd.month_start_date,
         dd.calendar_year AS dropoff_year, dd.month_start_date AS dropoff_month,
         pz.borough AS pickup_borough, f.pu_location_id,
         dz.borough AS dropoff_borough, f.do_location_id,
         pt.payment_type_name
  FROM nyctaxi.fact_trip f
  JOIN nyctaxi.dim_date pd ON pd.date_key = f.pickup_date
  JOIN nyctaxi.dim_date dd ON dd.date_key = f.dropoff_date
  JOIN nyctaxi.dim_zone pz ON pz.location_id = f.pu_location_id
  JOIN nyctaxi.dim_zone dz ON dz.location_id = f.do_location_id
  JOIN nyctaxi.dim_payment_type pt ON pt.payment_type = f.payment_type
)
SELECT grain, measure, member_1, member_2, member_3, value
FROM (
  SELECT 'total' AS grain, 'B-N1' AS measure, CAST(NULL AS STRING) AS member_1, CAST(NULL AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, COUNT(*) AS value
  FROM base
  UNION ALL
  SELECT 'year' AS grain, 'B-N1' AS measure, CAST(calendar_year AS STRING) AS member_1, CAST(NULL AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, COUNT(*) AS value
  FROM base
  GROUP BY calendar_year
  UNION ALL
  SELECT 'month' AS grain, 'B-N1' AS measure, CAST(month_start_date AS STRING) AS member_1, CAST(NULL AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, COUNT(*) AS value
  FROM base
  GROUP BY month_start_date
  UNION ALL
  SELECT 'day' AS grain, 'B-N1' AS measure, CAST(pickup_date AS STRING) AS member_1, CAST(NULL AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, COUNT(*) AS value
  FROM base
  GROUP BY pickup_date
  UNION ALL
  SELECT 'dropoff_year' AS grain, 'B-N1' AS measure, CAST(dropoff_year AS STRING) AS member_1, CAST(NULL AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, COUNT(*) AS value
  FROM base
  GROUP BY dropoff_year
  UNION ALL
  SELECT 'dropoff_month' AS grain, 'B-N1' AS measure, CAST(dropoff_month AS STRING) AS member_1, CAST(NULL AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, COUNT(*) AS value
  FROM base
  GROUP BY dropoff_month
  UNION ALL
  SELECT 'year_pickup_hour' AS grain, 'B-N1' AS measure, CAST(calendar_year AS STRING) AS member_1, CAST(pickup_hour AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, COUNT(*) AS value
  FROM base
  GROUP BY calendar_year, pickup_hour
  UNION ALL
  SELECT 'year_pickup_borough' AS grain, 'B-N1' AS measure, CAST(calendar_year AS STRING) AS member_1, CAST(pickup_borough AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, COUNT(*) AS value
  FROM base
  GROUP BY calendar_year, pickup_borough
  UNION ALL
  SELECT 'year_pickup_zone' AS grain, 'B-N1' AS measure, CAST(calendar_year AS STRING) AS member_1, CAST(pu_location_id AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, COUNT(*) AS value
  FROM base
  GROUP BY calendar_year, pu_location_id
  UNION ALL
  SELECT 'year_dropoff_borough' AS grain, 'B-N1' AS measure, CAST(calendar_year AS STRING) AS member_1, CAST(dropoff_borough AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, COUNT(*) AS value
  FROM base
  GROUP BY calendar_year, dropoff_borough
  UNION ALL
  SELECT 'year_dropoff_zone' AS grain, 'B-N1' AS measure, CAST(calendar_year AS STRING) AS member_1, CAST(do_location_id AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, COUNT(*) AS value
  FROM base
  GROUP BY calendar_year, do_location_id
  UNION ALL
  SELECT 'year_payment_type' AS grain, 'B-N1' AS measure, CAST(calendar_year AS STRING) AS member_1, CAST(payment_type_name AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, COUNT(*) AS value
  FROM base
  GROUP BY calendar_year, payment_type_name
  UNION ALL
  SELECT 'year_vendor' AS grain, 'B-N1' AS measure, CAST(calendar_year AS STRING) AS member_1, CAST(vendor_id AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, COUNT(*) AS value
  FROM base
  GROUP BY calendar_year, vendor_id
  UNION ALL
  SELECT 'year_pickup_dropoff_borough' AS grain, 'B-N1' AS measure, CAST(calendar_year AS STRING) AS member_1, CAST(pickup_borough AS STRING) AS member_2, CAST(dropoff_borough AS STRING) AS member_3, COUNT(*) AS value
  FROM base
  GROUP BY calendar_year, pickup_borough, dropoff_borough
) r
ORDER BY grain, measure, member_1 NULLS FIRST, member_2 NULLS FIRST, member_3 NULLS FIRST
